$ec_lang['lpn_inp_report_counts']='{nodes} nudos, embalses y depósitos, {links} tuberías, bombas y válvulas, en {units}.';
$ec_lang['lpn_inp_report_clean']='Todo el contenido del archivo se incorporó. No se dejó nada fuera.';
